INSERT INTO Language_ko_KR(Tag, Text)
VALUES	('TXT_KEY_BUILDING_SILO',			'미사일 격납고'),
		('TXT_KEY_BUILDING_SILO_TEXT',		'지하 미사일 격납고는 모든 종류의 탄도 미사일을 저장하고 발사하기 위해 지하에 건설된 수직 원통형 구조물입니다. 일반적으로 미사일 발사 통제 센터에 물리적으로 그리고/또는 전자적으로 연결되어 있습니다. 1960년대에 소련의 UR-100과 미국의 타이탄 II 미사일 시리즈가 도입되면서 지하 격납고는 현대적인 형태로 바뀌었습니다. 두 미사일 시리즈 모두 미사일에 저장할 수 있는 고속 추진제를 사용하여 빠른 발사가 가능해졌습니다. 이를 통해 두 나라의 액체연료 미사일 시스템을 지하 격납고로 옮길 수 있게 되었습니다. 그 이후로 지하 미사일 격납고는 대지 발사 미사일의 주요 미사일 기지 시스템이자 발사 시설로 남아 있습니다.'),
		('TXT_KEY_BUILDING_SILO_STRATEGY',	'마지막 군사 건물인 미사일 격납고를 사용해 도시를 정보 시대의 완전한 공성 유닛으로 바꾸세요. 수고에 대한 대가로 유도 미사일을 무료로 받을 수 있을 뿐만 아니라, 추가 미사일(핵 미사일 포함)은 반값으로 구매할 수 있으며 이는 몇 턴밖에 남지 않은 게임에서 막대한 건설 비용을 충당하는 셈입니다.'),
		('TXT_KEY_BUILDING_SILO_HELP',		'Receive a [COLOR_POSITIVE_TEXT]Free[ENDCOLOR] Guided Missile. +100% [ICON_PRODUCTION] Production to Missile Units and Missiles created by this City (past or future) receive the [COLOR_POSITIVE_TEXT]Shielded Silo[ENDCOLOR] Promotion. +25% to the City''s [ICON_RANGE_STRENGTH] Ranged Strike Damage, and +1 to its Ranged Strike Range.[NEWLINE][NEWLINE]Requires 1 [ICON_RES_ALUMINUM] Aluminum.');